        'v079' => ['tipo' => 'post', 'slug' => 'opposizione-decreto-ingiuntivo-40-giorni-cosa-fare', 'campo' => 'post_content',
            'cerca' => 'si propone con atto di citazione davanti allo stesso ufficio giudiziario che ha emesso il decreto (articolo 645).',
            'sostituisci' => 'si propone davanti all’ufficio giudiziario al quale appartiene il giudice che ha emesso il decreto (articolo 645), con l’atto introduttivo richiesto dal rito applicabile: di regola l’atto di citazione davanti al tribunale; il ricorso nelle materie soggette al rito del lavoro o al rito locatizio; davanti al giudice di pace, le forme del procedimento semplificato (articolo 316).'],
        'v080' => ['tipo' => 'post', 'slug' => 'opposizione-decreto-ingiuntivo-40-giorni-cosa-fare', 'campo' => 'post_content',
            'cerca' => 'Con la citazione il debitore',
            'sostituisci' => 'Con l’atto di opposizione il debitore'],
        'v081' => ['tipo' => 'post', 'slug' => 'opposizione-decreto-ingiuntivo-40-giorni-cosa-fare', 'campo' => 'post_content',
            'cerca' => 'L’atto va notificato al creditore entro il termine di quaranta giorni: è la notifica dell’atto di citazione, non il suo deposito, a impedire la decadenza.',
            'sostituisci' => 'Quando l’opposizione si propone con citazione, l’atto va notificato al creditore entro il termine di quaranta giorni: è la notifica, non il deposito, a impedire la decadenza. Quando invece va proposta con ricorso, come nelle materie del lavoro e delle locazioni, conta il deposito del ricorso in cancelleria entro lo stesso termine: una citazione soltanto notificata in tempo non basta.'],
        'v082' => ['tipo' => 'post', 'slug' => 'opposizione-decreto-ingiuntivo-40-giorni-cosa-fare', 'campo' => 'post_content',
            'cerca' => 'il decreto diventa definitivo e non è più discutibile nel merito.',
            'sostituisci' => 'il decreto diventa definitivo e, salvi i casi eccezionali di opposizione tardiva previsti dall’articolo 650, non è più discutibile nel merito.'],
        'v083' => ['tipo' => 'post', 'slug' => 'opposizione-decreto-ingiuntivo-40-giorni-cosa-fare', 'campo' => 'post_content',
            'cerca' => 'quando la notifica del decreto era irregolare, oppure quando il debitore non ha potuto conoscere il decreto per caso fortuito o forza maggiore.',
            'sostituisci' => 'quando il debitore prova di non aver avuto tempestiva conoscenza del decreto per irregolarità della notificazione o per caso fortuito o forza maggiore, oppure quando, pur conoscendolo, non ha potuto opporsi in tempo per caso fortuito o forza maggiore (Corte costituzionale, sentenza n. 120 del 1976). Per il consumatore, inoltre, le Sezioni Unite della Cassazione (sentenza 6 aprile 2023, n. 9479) ammettono l’opposizione tardiva, limitata al carattere abusivo delle clausole del contratto, quando il decreto non motiva sul controllo di tali clausole e non contiene l’avvertimento sulle conseguenze della mancata opposizione: in questo caso il limite dei dieci giorni non si applica e il termine è di quaranta giorni.'],
        'v084' => ['tipo' => 'post', 'slug' => 'opposizione-decreto-ingiuntivo-40-giorni-cosa-fare', 'campo' => 'post_content',
            'cerca' => 'e comunque l’opposizione tardiva non è più proponibile una volta decorsi dieci giorni dal primo atto di esecuzione',
            'sostituisci' => 'e, fuori dal caso del consumatore appena descritto, l’opposizione tardiva non è più proponibile una volta decorsi dieci giorni dal primo atto di esecuzione'],
        'v085' => ['tipo' => 'post', 'slug' => 'opposizione-decreto-ingiuntivo-40-giorni-cosa-fare', 'campo' => 'post_content',
            'cerca' => 'se il decreto viene notificato all’estero valgono termini più lunghi, stabiliti dalla legge in base allo Stato di destinazione;',
            'sostituisci' => 'se l’intimato risiede in un altro Stato dell’Unione europea il termine è di cinquanta giorni e può essere ridotto fino a venti; se risiede in uno Stato non appartenente all’Unione è di sessanta giorni e il giudice può fissarlo tra trenta e centoventi: anche in questi casi vale il termine indicato nel decreto;'],
        'v086' => ['tipo' => 'post', 'slug' => 'opposizione-decreto-ingiuntivo-40-giorni-cosa-fare', 'campo' => 'post_content',
            'cerca' => 'il giudice la concede se l’opposizione non è fondata su prova scritta o di pronta soluzione.',
            'sostituisci' => 'il giudice può concederla se l’opposizione non è fondata su prova scritta o di pronta soluzione; deve concederla per le somme non contestate, salvo che l’opposizione sia proposta per vizi procedurali. Se il creditore offre cauzione per le eventuali restituzioni, spese e danni, il giudice può concederla, ma solo dopo aver valutato le prove e l’adeguatezza della cauzione (Corte costituzionale, sentenza n. 137 del 1984).'],
        'v087' => ['tipo' => 'post', 'slug' => 'quando-un-genitore-ostacola-il-rapporto-con-laltro-lelusione-dei-provvedimenti-sullaffidamento-e-lart-388-comma-2-del-codice-penale', 'campo' => 'post_content',
            'cerca' => 'mero inadempimento occasionale non integra il reato',
            'sostituisci' => 'semplice inadempimento, privo di carattere elusivo, non integra il reato'],
        'v088' => ['tipo' => 'post', 'slug' => 'quando-un-genitore-ostacola-il-rapporto-con-laltro-lelusione-dei-provvedimenti-sullaffidamento-e-lart-388-comma-2-del-codice-penale', 'campo' => 'post_content',
            'cerca' => 'La singola visita negata, il ritardo isolato nella riconsegna del minore, l’episodio sporadico restano fuori dall’area penale: occorre qualcosa di più di una semplice inosservanza.',
            'sostituisci' => 'Una visita saltata per un contrattempo o un ritardo nella riconsegna del minore non bastano, di per sé, a integrare il reato: occorre una condotta che eluda il provvedimento. Il numero degli episodi, però, non è decisivo: anche un solo comportamento elusivo, se idoneo a frustrare gli effetti della decisione del giudice, può integrare il reato (Cass. pen., Sez. VI, 16 febbraio 2026, n. 6181).'],
        'v089' => ['tipo' => 'post', 'slug' => 'quando-un-genitore-ostacola-il-rapporto-con-laltro-lelusione-dei-provvedimenti-sullaffidamento-e-lart-388-comma-2-del-codice-penale', 'campo' => 'post_content',
            'cerca' => 'In questo senso si è espressa più volte la Suprema Corte, escludendo la rilevanza penale di violazioni singole e occasionali, prive del carattere della sistematicità.',
            'sostituisci' => 'La reiterazione degli episodi resta comunque un indice importante della volontà elusiva.'],
        'v090' => ['tipo' => 'post', 'slug' => 'quando-un-genitore-ostacola-il-rapporto-con-laltro-lelusione-dei-provvedimenti-sullaffidamento-e-lart-388-comma-2-del-codice-penale', 'campo' => 'post_content',
            'cerca' => 'occasionalità e sistematicità',
            'sostituisci' => 'semplice inadempimento e condotta elusiva'],
        'v091' => ['tipo' => 'post', 'slug' => 'trattenere-tuo-figlio-puo-essere-reato', 'campo' => 'post_content',
