        'v247' => ['tipo' => 'post', 'slug' => 'invalidita-civile-iter-giudiziario', 'campo' => 'post_content',
            'cerca' => 'dopo il deposito della relazione di ATP, entro un termine perentorio fissato da giudice ma comunque non superiore a 30 gg., le parti dovranno depositare atto scritto di accettazione o di contestazione della CTU; il mancato deposito è considerata accettazione implicita;',
            'sostituisci' => 'dopo il deposito della relazione di ATP, comunicato dalla cancelleria, le parti che intendono contestare le conclusioni del CTU devono depositare la relativa dichiarazione entro il termine perentorio di trenta giorni dalla comunicazione; il mancato deposito equivale ad accettazione (Nota di aggiornamento (ottobre 2026): così l\'art. 445-bis, quarto comma, c.p.c., come sostituito dal d.l. 117/2025; in precedenza il termine, non superiore a trenta giorni, era fissato dal giudice);'],
        'v248' => ['tipo' => 'post', 'slug' => 'invalidita-civile-iter-giudiziario', 'campo' => 'post_content',
            'cerca' => 'l’accettazione provoca la omologazione giudiziale della CTU; con il provvedimento il giudice provvede anche alla ripartizione della spese;',
            'sostituisci' => 'in assenza di contestazione il giudice omologa con decreto l\'accertamento del requisito sanitario e provvede anche sulle spese;'],
        'v249' => ['tipo' => 'post', 'slug' => 'invalidita-civile-iter-giudiziario', 'campo' => 'post_content',
            'cerca' => 'se la CTU viene contestata da una delle parti entro il termine indicato dal giudice tramite deposito di note di contestazione, anche prive di motivazione, allora si può avviare un ricorso giudiziario che avverrà nella forma consueta;',
            'sostituisci' => 'se una delle parti deposita nel termine la dichiarazione di dissenso, essa deve poi depositare, entro il termine perentorio di trenta giorni dalla dichiarazione, il ricorso introduttivo del giudizio, specificando a pena di inammissibilità i motivi della contestazione (art. 445-bis, sesto comma, c.p.c.);'],
        'v250' => ['tipo' => 'post', 'slug' => 'invalidita-civile-iter-giudiziario', 'campo' => 'post_content',
            'cerca' => 'con il supporto di documentazione medica ed eventualmente di una consulenza di parte si da inizio all’azione legale che prevede la nomina di un altro CTU, che visitato il ricorrente e valutata la documentazione sanitaria, proporrà al giudice le proprie valutazioni;',
            'sostituisci' => 'con il supporto di documentazione medica ed eventualmente di una consulenza di parte si dà inizio all\'azione legale, nel corso della quale il giudice può disporre una nuova consulenza tecnica d\'ufficio che, visitato il ricorrente e valutata la documentazione sanitaria, proporrà al giudice le proprie valutazioni;'],
