        'v299' => ['tipo' => 'post', 'slug' => 'meno-tasse-sportivi-dilettanti-cori-bande-musicali-dilettantistiche', 'campo' => 'post_content',
            'cerca' => 'in luogo del precedente limite di 7.000,00 euro',
            'sostituisci' => 'in luogo del precedente limite di 7.500,00 euro'],
        'v300' => ['tipo' => 'post', 'slug' => 'meno-tasse-sportivi-dilettanti-cori-bande-musicali-dilettantistiche', 'campo' => 'post_content',
            'cerca' => 'L’ art. 25co.1 della legge 133/1999 dispone che la “ritenuta è a titolo imponibile che eccede il predetto importo”.',
            'sostituisci' => 'L\'art. 25, comma 1, della legge 133/1999 prevedeva che la ritenuta fosse «a titolo d\'imposta per la parte imponibile dei suddetti redditi compresa fino a lire 40 milioni» (euro 20.658,28) e «a titolo di acconto per la parte imponibile che eccede il predetto importo».'],
        'v301' => ['tipo' => 'post', 'slug' => 'meno-tasse-sportivi-dilettanti-cori-bande-musicali-dilettantistiche', 'campo' => 'post_content',
            'cerca' => '– Con la soglia di 7.500,00 euro, la ritenuta a titolo d’imposta che si applicava fino a 28.158,28 euro con la soglia di a 10.000,00 euro, la ritenuta a titolo di imposta si applica fino a 30.658,29 euro.',
            'sostituisci' => '– con la soglia di 7.500,00 euro la ritenuta a titolo d\'imposta si applicava fino a 28.158,28 euro di compensi; con la soglia di 10.000,00 euro si applicava fino a 30.658,28 euro. Nota di aggiornamento (ottobre 2026): dal 1° luglio 2023 i compensi di lavoro sportivo nell\'area del dilettantismo seguono la riforma del d.lgs. 36/2021 e non costituiscono base imponibile fino a 15.000 euro annui (art. 36, comma 6); l\'art. 67, comma 1, lett. m), del TUIR riguarda ormai solo i compensi per direttori artistici e collaboratori tecnici di cori, bande musicali e filodrammatiche dilettantistiche, esenti fino a 10.000 euro (art. 69, comma 2, TUIR). Il comma 1 dell\'art. 25 della legge 133/1999 risulta abrogato dal d.lgs. 33/2025 con effetto dal 1° gennaio 2027.'],
        'v302' => ['tipo' => 'post', 'slug' => 'separazione-o-divorzio-mediante-negoziazione-assistita-da-avvocati', 'campo' => 'post_content',
